import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, uniform, float, abs, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, Shape, ShapeGeometry, DirectionalLight,
  } = ctx.THREE;

  const COLORS = {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    hairline: '#2a2a33',
    rowline: '#23232b',
    gradTop: '#ff4450',
    gradBot: '#c1121f',
  };

  const group = new Group();
  const disposables = [];
  const timelines = [];

  const track = (obj) => { disposables.push(obj); return obj; };

  function roundedRectGeometry(w, h, r) {
    const s = new Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return track(new ShapeGeometry(s, 6));
  }

  // ---------- BACKDROP STAGE (7 x 6 at z = -2.5) ----------
  const backdropMat = track(new MeshBasicNodeMaterial());
  backdropMat.colorNode = mix(
    color(COLORS.background),
    color(COLORS.surface),
    smoothstep(float(0.0), float(1.0), uv().y).mul(0.85)
  );
  const backdrop = new Mesh(track(new PlaneGeometry(7, 6)), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---------- NODE-LOCAL LIGHTS ----------
  const rim = new DirectionalLight(COLORS.accent, 1.1);
  rim.position.set(3, -2.5, 2.5);
  group.add(rim);
  const fill = new DirectionalLight(COLORS.paper, 0.5);
  fill.position.set(-3.5, 3, 3);
  group.add(fill);

  // ---------- CARD GROUP ----------
  const cardGroup = new Group();
  group.add(cardGroup);

  const CARD_W = 2.4, CARD_H = 3.2, RADIUS = 0.06, PAD = 0.5;
  const LEFT = -CARD_W / 2 + PAD;

  // hairline border plate
  const borderMat = track(new MeshBasicNodeMaterial({ color: COLORS.hairline }));
  const borderMesh = new Mesh(roundedRectGeometry(CARD_W + 0.012, CARD_H + 0.012, RADIUS + 0.006), borderMat);
  borderMesh.position.z = -0.015;
  cardGroup.add(borderMesh);

  // card face
  const cardMat = track(new MeshStandardNodeMaterial({
    color: COLORS.surface, roughness: 0.62, metalness: 0.15,
  }));
  const cardMesh = new Mesh(roundedRectGeometry(CARD_W, CARD_H, RADIUS), cardMat);
  cardGroup.add(cardMesh);

  // ---------- MACHINED HEADER STRIP with animated specular sweep ----------
  const sweep = uniform(-0.4);
  const headerMat = track(new MeshPhysicalNodeMaterial({
    roughness: 0.55, metalness: 0.5, clearcoat: 0.2,
  }));
  const brushed = sin(uv().x.mul(620.0)).mul(0.035);
  const band = smoothstep(float(0.28), float(0.0), abs(uv().x.sub(sweep)));
  headerMat.colorNode = mix(
    color(COLORS.surface).add(brushed),
    color(COLORS.paper),
    band.mul(0.55).add(0.14)
  );
  const headerMesh = new Mesh(track(new PlaneGeometry(CARD_W, 0.08)), headerMat);
  headerMesh.position.set(0, CARD_H / 2 - 0.04, 0.006);
  cardGroup.add(headerMesh);

  // ---------- TEXT CONTENT (verbatim from spec) ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((i) => i.role === role);
  const textObjects = [];

  function addText(item, opts, x, y, z, parent) {
    if (!item) return null;
    const t = ctx.fontAtlas.createText(String(item.text), opts);
    t.position.set(x, y, z);
    (parent || cardGroup).add(t);
    textObjects.push(t);
    return t;
  }

  const tierItem = byRole('tier-name')[0];
  const priceItem = byRole('price')[0];
  const captionItem = byRole('caption')[0];
  const featureItems = byRole('feature');
  const ctaItem = byRole('cta-label')[0];

  addText(tierItem, {
    fontSize: tierItem?.typography?.fontSize ?? 20,
    color: COLORS.paper, align: 'left', letterSpacingPx: 1.6,
  }, LEFT, 1.06, 0.008);

  addText(priceItem, {
    fontSize: priceItem?.typography?.fontSize ?? 62,
    color: COLORS.paper, align: 'left',
  }, LEFT, 0.66, 0.008);

  addText(captionItem, {
    fontSize: captionItem?.typography?.fontSize ?? 9,
    color: COLORS.paper, align: 'left', letterSpacingPx: 1.1,
  }, LEFT, 0.34, 0.008);

  // ---------- FEATURE ROWS with hairline separators ----------
  const rowMat = track(new MeshBasicNodeMaterial({ color: COLORS.rowline }));
  const rowLineGeo = track(new PlaneGeometry(CARD_W - 2 * PAD, 0.006));
  const featureRows = [];
  const rowCenters = [0.10, -0.18, -0.46, -0.74];

  featureItems.forEach((item, i) => {
    const row = new Group();
    const y = rowCenters[i] ?? (0.10 - i * 0.28);
    row.position.set(0, y, 0.008);
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 13,
      color: COLORS.paper, align: 'left',
    });
    t.position.set(LEFT, 0, 0);
    textObjects.push(t);
    row.add(t);
    if (i < featureItems.length - 1) {
      const line = new Mesh(rowLineGeo, rowMat);
      line.position.set(0, -0.14, 0);
      row.add(line);
    }
    cardGroup.add(row);
    featureRows.push(row);
  });

  // ---------- CTA ROW (the single brightest element) ----------
  const ctaGroup = new Group();
  ctaGroup.position.set(0, -1.15, 0.012);
  cardGroup.add(ctaGroup);

  const ctaMat = track(new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.2 }));
  ctaMat.colorNode = mix(color(COLORS.gradBot), color(COLORS.gradTop), uv().y);
  const edgeX = abs(uv().x.sub(0.5)).mul(2.0);
  const edgeY = abs(uv().y.sub(0.5)).mul(2.0);
  const borderMask = smoothstep(float(0.86), float(0.98), edgeX.max(edgeY));
  ctaMat.emissiveNode = color(COLORS.accent).mul(borderMask).mul(1.5);
  const ctaMesh = new Mesh(track(new PlaneGeometry(1.4, 0.36)), ctaMat);
  ctaGroup.add(ctaMesh);

  addText(ctaItem, {
    fontSize: ctaItem?.typography?.fontSize ?? 13,
    color: COLORS.ink, align: 'center', letterSpacingPx: 1.2,
  }, 0, 0, 0.006, ctaGroup);

  // ---------- MOTION ----------
  // Weighted settle + specular sweep across header
  cardGroup.scale.setScalar(1.04);
  const settleTl = gsap.timeline();
  settleTl.to(cardGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  settleTl.to(sweep, { value: 1.4, duration: 0.9, ease: 'power2.inOut' }, 0);
  timelines.push(settleTl);

  // Feature rows: fade-up stagger
  const rowMats = [];
  featureRows.forEach((row) => {
    row.userData.baseY = row.position.y;
    row.position.y += 0.2;
    row.traverse((o) => {
      if (o.material && o.material !== rowMat) {
        o.material.transparent = true;
        o.material.opacity = 0;
        rowMats.push(o.material);
      }
    });
  });
  const rowTl = gsap.timeline({ delay: 0.15 });
  featureRows.forEach((row, i) => {
    rowTl.to(row.position, {
      y: row.userData.baseY, duration: 0.5, ease: 'power2.out',
    }, i * 0.08);
  });
  rowTl.to(rowMats, { opacity: 1, duration: 0.5, ease: 'power2.out', stagger: 0.02 }, 0);
  timelines.push(rowTl);

  // Idle: single slow breathing on card, <= 2%
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.1 });
  idleTl.to(cardGroup.scale, { x: 1.012, y: 1.012, z: 1.012, duration: 3.2, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---------- HANDLERS ----------
  group.userData.handlers = {
    click: () => {
      const press = gsap.timeline();
      press.to(ctaGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' });
      press.to(ctaGroup.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out(1.4)' });
      timelines.push(press);
      ctx.emit('cta', { action: 'join-reserve', tier: 'atelier-reserve' });
    },
    pointerenter: () => {
      gsap.to(cardGroup.rotation, { y: 0.06, x: -0.03, duration: 0.3, ease: 'power2.out' });
    },
    pointerleave: () => {
      gsap.to(cardGroup.rotation, { y: 0, x: 0, duration: 0.3, ease: 'power2.out' });
    },
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    gsap.killTweensOf(cardGroup.scale);
    gsap.killTweensOf(cardGroup.rotation);
    gsap.killTweensOf(ctaGroup.scale);
    disposables.forEach((d) => { if (d.dispose) d.dispose(); });
    textObjects.forEach((t) => {
      t.traverse((o) => {
        if (o.geometry && o.geometry.dispose) o.geometry.dispose();
        if (o.material && o.material.dispose) o.material.dispose();
      });
    });
    group.clear();
  };

  return group;
}
